-- The ids the ship is issued with, in shelf order. TREK_Build
-- reads this to stock the tape shelf, so a tape added above
-- reaches the shelf without a second list to keep in step.
TREK_TapeIds = {
    "TREK_TalentNight",
    "TREK_Tuvix",
    "TREK_LogOne",
    "TREK_LogTwo",
    "TREK_LogThree",
    "TREK_LogFour",
    "TREK_LogFive",
    "TREK_LogSix",
    "TREK_Prisoner",
    "TREK_KimExam",
    "TREK_Morn",
    "TREK_Uxbridge",
}

-- Every tape this mod registers, the issued ones included: the
-- registration below has to cover a tape that is not on the shelf
-- yet, or it arrives blank.
TREK_AllTapeIds = {
    "TREK_TalentNight",
    "TREK_Tuvix",
    "TREK_LogOne",
    "TREK_LogTwo",
    "TREK_LogThree",
    "TREK_LogFour",
    "TREK_LogFive",
    "TREK_LogSix",
    "TREK_Prisoner",
    "TREK_KimExam",
    "TREK_Morn",
    "TREK_Uxbridge",
    "TREK_EnsignLog",
    "TREK_GoldOne",
    "TREK_GoldTwo",
    "TREK_GoldThree",
    "TREK_GoldFour",
    "TREK_GoldFive",
    "TREK_GoldSix",
}

Events.OnInitRecordedMedia.Add(function(rc)
    if not rc then return end
    for _, id in ipairs(TREK_AllTapeIds) do
        local known = nil
        local ok = pcall(function() known = rc:getMediaData(id) end)
        if ok and not known then
            local v = RecMedia[id]
            if v then
                local data = rc:register(v.category, id,
                                         v.itemDisplayName, v.spawning or 0)
                if data then
                    if v.title then data:setTitle(v.title) end
                    if v.subtitle then data:setSubtitle(v.subtitle) end
                    if v.author then data:setAuthor(v.author) end
                    if v.extra then data:setExtra(v.extra) end
                    for _, j in ipairs(v.lines) do
                        data:addLine(j.text, j.r, j.g, j.b, j.codes)
                    end
                end
            end
        end
    end
end)
